agentic/g4-verification-engineering.solution:
const norm = (s) => s.replace(/\s+/g, ' ').trim();

export async function wrongSolutionFilter(task, run) {
  if (norm(task.reference) === norm(task.wrong)) {
    return { verdict: 'reject', reason: 'deliberately wrong solution is identical to the reference' };
  }
  let ref;
  try {
    ref = await run(task.reference);
  } catch (err) {
    return { verdict: 'reject', reason: `reference not executed: ${err.message}` };
  }
  if (!ref.loaded || ref.timedOut || !ref.pass) {
    return { verdict: 'reject', reason: 'the test does not PASS the reference solution' };
  }
  let wrong;
  try {
    wrong = await run(task.wrong);
  } catch (err) {
    return { verdict: 'reject', reason: `wrong solution not executed: ${err.message}` };
  }
  if (wrong.pass) return { verdict: 'reject', reason: 'the deliberately wrong solution PASSES the test' };
  if (!wrong.loaded || wrong.timedOut) {
    return { verdict: 'reject', reason: 'the wrong solution only fails by not loading / timing out' };
  }
  if (!wrong.failures.some((f) => f.name && !f.name.startsWith('('))) {
    return { verdict: 'reject', reason: 'the wrong solution must fail a NAMED test' };
  }
  return { verdict: 'accept', reason: 'reference passes; wrong solution loads and fails a named test' };
}
